def label(blocked):
    ids, count = ({}, 0)
    for p in sorted(land):
        if p in ids:
            continue
        count += 1
        ids[p] = count
        queue = deque([p])
        while queue:
            cur = queue.popleft()
            for n in neighbors(cur):
                if n in land and n not in ids and (frozenset((cur, n)) not in blocked):
                    ids[n] = count
                    queue.append(n)
    return ids

def find(i):
    parent.setdefault(i, i)
    while parent[i] != i:
        parent[i] = parent[parent[i]]
        i = parent[i]
    return i

