def allowed_next(mask):
    got = support.get(mask)
    if got is None:
        got = 0
        m, i = (mask, 0)
        while m:
            if m & 1:
                got |= compat[i]
            m >>= 1
            i += 1
        support[mask] = got
    return got

def propagate(queue):
    while queue:
        p = queue.pop()
        allow = allowed_next(domain[p])
        for n in near[p]:
            if n in result:
                continue
            nd = domain[n] & allow
            if nd != domain[n] and nd:
                domain[n] = nd
